//! Bindings for the RKLLM runtime, generated by `build.rs` from the vendored
//! `include/rkllm.h` (runtime 1.3.0) and resolved from `librkllmrt.so` at run
//! time. bindgen also emits compile-time size and offset assertions for every
//! struct, so a layout mismatch fails the build.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/rkllm.rs"));

/// The A76 big cores on RK3588.
pub const BIG_CORES_MASK: u32 = CPU4 | CPU5 | CPU6 | CPU7;

/// dlopen `lib` (a path, or a bare name searched on `LD_LIBRARY_PATH`) and
/// resolve every function in the header, so a wrong or mismatched library
/// fails here rather than inside `rkllm_init`.
pub fn load(lib: &str) -> anyhow::Result<RkllmLib> {
    // SAFETY: loading the vendor runtime runs its initializers; it has no
    // other load-time side effects.
    unsafe { RkllmLib::new(lib) }.map_err(|e| anyhow::anyhow!("dlopen {lib}: {e}"))
}

